CREATE TABLE finance_budget (id UUID PRIMARY KEY DEFAULT uuid_v7(),ledger_id UUID NOT NULL,owner_id UUID NOT NULL,category_id UUID NOT NULL,month DATE NOT NULL,amount NUMERIC(19,4) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),version BIGINT NOT NULL DEFAULT 0,CHECK(amount>=0),FOREIGN KEY(ledger_id) REFERENCES finance_ledger(id),FOREIGN KEY(category_id) REFERENCES finance_category(id),UNIQUE(ledger_id,category_id,month));
